import{_ as a,a as t,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 7 Too late","description":"学习 过去进行时与叙事背景，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 7 Too late","description":"学习 过去进行时与叙事背景，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 过去进行时与叙事背景，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 6 Percy Buttons","link":"/life/english/new-concept/book-2/unit-01/lesson-006"},"next":{"text":"第二册：实践与进步 · Lesson 8 The best and the worst","link":"/life/english/new-concept/book-2/unit-01/lesson-008"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 6 Percy Buttons","link":"/life/english/new-concept/book-2/unit-01/lesson-006"},"next":{"text":"第二册：实践与进步 · Lesson 8 The best and the worst","link":"/life/english/new-concept/book-2/unit-01/lesson-008"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/lesson-007.md","filePath":"life/english/new-concept/book-2/unit-01/lesson-007.md"}'),o={name:"life/english/new-concept/book-2/unit-01/lesson-007.md"};function r(l,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第二册-实践与进步-·-lesson-7-too-late" tabindex="-1">第二册：实践与进步 · Lesson 7 Too late <a class="header-anchor" href="#第二册-实践与进步-·-lesson-7-too-late" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 7 Too late&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>包裹终于送到，但等候的人已经离开；练习用背景活动和突然发生的事件组织叙述。本课的语言观察是：were waiting 表示快递到达时仍持续的背景；arrived 给出发生的时间点。不要把两个动作都写成进行时而失去推动故事的事件。完成学习后，请写一次“赶到时已经晚了”的事件，至少包含一个背景动作。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>guard</td><td>/ɡɑːd/</td><td>n.</td><td>守卫</td><td>a security guard</td></tr><tr><td>parcel</td><td>/ˈpɑːsəl/</td><td>n.</td><td>包裹</td><td>deliver a parcel</td></tr><tr><td>empty</td><td>/ˈempti/</td><td>adj.</td><td>空的</td><td>an empty box</td></tr><tr><td>wait</td><td>/weɪt/</td><td>v.</td><td>等候</td><td>wait patiently</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>wait for — 等待某人或某物，不能漏 for</li><li>too late to do — 太迟而不能做某事</li></ul><h2 id="语法讲解-过去进行时与叙事背景" tabindex="-1">语法讲解：过去进行时与叙事背景 <a class="header-anchor" href="#语法讲解-过去进行时与叙事背景" aria-label="Permalink to &quot;语法讲解：过去进行时与叙事背景&quot;">​</a></h2><p>过去进行时由 was/were 加动词 -ing 构成，描述过去某个时刻正在展开的活动。它常与一般过去时配合：进行时给出背景，过去式指出发生在背景中的事件。when 与 while 的选择取决于从句表达瞬间还是过程，不能把两者当作机械的时态开关。两个同时持续的活动也可都用进行时，而状态动词往往仍用简单时态。本课应用：were waiting 表示快递到达时仍持续的背景；arrived 给出发生的时间点。不要把两个动作都写成进行时而失去推动故事的事件。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The guards were checking the gate when the parcel arrived.</p></blockquote><p>包裹送到时，守卫正在检查大门。</p><p>主句 were checking 是背景，when 从句 arrived 是介入事件；guards 是复数，所以不能用 was。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>The guards was checking 主谓不一致；checking 是活动，不应以 checked 代替 -ing 来构成进行时。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>将 when 前后分组朗读，重读 checking 与 arrived，比较过程和瞬间的节奏。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The guards were checking the gate when the parcel arrived. The driver waited outside. By then, the visitor had already left.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写一次“赶到时已经晚了”的事件，至少包含一个背景动作。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：主句 were checking 是背景，when 从句 arrived 是介入事件；guards 是复数，所以不能用 was。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：The guards was checking 主谓不一致；checking 是活动，不应以 checked 代替 -ing 来构成进行时。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 was/were：The guards ___ checking the gate.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were</p><p><strong>解析：</strong> guards 是复数主语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>快递到达时，访客是否仍在？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> No. The visitor had already left.</p><p><strong>解析：</strong> had already left 表示访客在那个过去时刻之前离开。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 when 合并：I was waiting. The bell rang.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I was waiting when the bell rang.</p><p><strong>解析：</strong> 等待是持续背景，铃响是发生的事件。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去进行时与叙事背景。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-006">上一课</a> · <a href="/life/english/new-concept/book-2/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-008">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
